1	<script setup lang="ts">
2	/**
3	 * Plain-text, keyboard-first conversation reader (UX-02). Opening is read-only —
4	 * never marks read.
5	 *
6	 * Visit-scoped message state (active message, expansion, details disclosure,
7	 * scroll anchor) lives inside this mounted reader instance, keyed by
8	 * account+conversation reference and message ID — never by array position. It
9	 * survives J/K round trips and same-reference background replacements within
10	 * the reader session and is released when the reader closes (component
11	 * unmount) or the account changes.
12	 *
13	 * Archive/read controls are shown only when the authoritative capability permits them, and
14	 * Gmail-supplied plain-text limitations are disclosed explicitly (`unsupportedReason`,
15	 * `contextComplete === false`) instead of silently dropping content.
16	 *
17	 * Safety: message content is rendered exclusively through text interpolation
18	 * ({{ }}). No v-html, no markdown/HTML processing, no remote assets anywhere in
19	 * this slice — hostile markup stays literal text. Reply preparation always
20	 * targets the explicitly displayed latest message, never the focused message.
21	 *
22	 * Message commands (N/P/O/Shift+O, details dismissal) are exposed as narrow
23	 * methods for App's single keyboard dispatcher — this component never adds its
24	 * own window listener.
25	 */
26	import { actionLabel } from '../lib/browsing-actions';
27	import { fullDateLabel, machineDateTime } from '../lib/browsing-dates';
28	import { computed, nextTick, reactive, ref, watch } from 'vue';
29	import type { Address, Conversation, ConversationRef, DraftSource, MailError, Message } from '../lib/ipc/client';
30	import type { DetailState } from '../composables/useMailbox';
31	
32	const props = defineProps<{
33	  conversation: Conversation | null;
34	  state: DetailState;
35	  error: MailError | null;
36	  commandInFlight: boolean;
37	  /** The conversation reference the shell currently wants displayed. */
38	  openRef: ConversationRef | null;
39	  /** Gmail mode: archive/unarchive controls are hidden, not just disabled. */
40	  readOnly?: boolean;
41	  browsingOnly?: boolean;
42	  navigationUnavailable?: boolean;
43	  showReadControls?: boolean;
44	  /** Nonzero: shared controls dispatch to the SELECTION (§3.3), so the reader
45	   * offers explicit count-labelled desired-state controls instead of the open
46	   * conversation's single-state toggles (mixed selections included). */
47	  selectionCount?: number;
48	  selectionContext?: 'inbox' | 'saved' | 'done' | 'starred' | 'search';
49	}>();
50	
51	const emit = defineEmits<{
52	  close: [];
53	  attachments: [origin: HTMLElement];
54	  archive: [];
55	  unarchive: [];
56	  setRead: [read: boolean];
57	  prepareReply: [source: DraftSource];
58	  /** Identity of the message that currently owns reader focus. */
59	  activeMessage: [messageId: string | null];
60	  /** Hover/focus participant context override; `null` restores the baseline. */
61	  contactOverride: [
62	    override:
63	      | { ref: ConversationRef; messageId: string; displayName: string | null; mailbox: string }
64	      | null,
65	  ];
66	}>();
67	
68	const container = ref<HTMLElement | null>(null);
69	const scrollerEl = ref<HTMLElement | null>(null);
70	const messageEls = new Map<string, HTMLElement>();
71	
72	/** Selected-scope toolbar mode: nonzero selection dispatches to the whole
73	 * selection with explicit count labels (§3.3); null keeps single behavior. */
74	const bulkScope = computed(() =>
75	  (props.selectionCount ?? 0) > 0
76	    ? { count: props.selectionCount!, context: props.selectionContext ?? 'inbox' }
77	    : null,
78	);
79	
80	type StarCoverage = NonNullable<Conversation['stars']>;
81	
82	/** Short visible star line; exact coverage moves to the title/description. */
83	function starSummary(stars: StarCoverage): string {
84	  if (stars.starredMessages > 0) return stars.knownMessages < stars.totalMessages ? 'Starred (partial)' : 'Starred';
85	  return stars.knownMessages === stars.totalMessages && stars.totalMessages > 0 ? 'Not starred' : 'Star state unknown';
86	}
87	
88	function starCoverageDetail(stars: StarCoverage): string {
89	  return `Effective star values known for ${stars.knownMessages} of ${stars.totalMessages} cached messages. Pending intent is not provider confirmation.`;
90	}
91	
92	const latestMessage = computed(() => props.conversation?.messages.at(-1) ?? null);
93	const replyBlockedReason = computed(() => {
94	  if (!props.conversation || !latestMessage.value) return 'No displayed latest message is available as a reply source.';
95	  if (props.conversation.retainedSnapshotAt) return 'Reply preparation is blocked for a retained snapshot; current message headers cannot be verified.';
96	  if (props.conversation.contextComplete === false) return 'Reply preparation is blocked because this cached conversation is incomplete.';
97	  if (props.conversation.replyContext && props.conversation.replyContext.sourceMessageId !== latestMessage.value.id) return 'Reply preparation is blocked because cached reply headers do not match the displayed latest message.';
98	  return null;
99	});
100	
101	function prepareReply(): void {
102	  // Reply always targets the explicitly displayed latest message; focusing an
103	  // older message never changes the reply contract.
104	  const conversation = props.conversation;
105	  const source = latestMessage.value;
106	  if (!conversation || !source || replyBlockedReason.value) return;
107	  emit('prepareReply', {
108	    kind: 'reply',
109	    conversation: { ...conversation.ref },
110	    sourceMessageId: source.id,
111	  });
112	}
113	
114	function describeError(error: MailError): string {
115	  switch (error.kind) {
116	    case 'not_found':
117	      return 'That conversation is no longer available.';
118	    case 'invalid_request':
119	      return `The request was rejected (invalid field: ${error.field}).`;
120	    case 'request_id_conflict':
121	      return 'The request conflicted with an earlier request ID.';
122	    case 'storage_unavailable':
123	      return 'Local storage is unavailable. The operation was not confirmed.';
124	    case 'profile_in_use':
125	      return 'Another window is using this profile.';
126	    case 'read_only':
127	      return 'Gmail is read-only; archiving is unavailable.';
128	    case 'not_configured':
129	      return 'Gmail is not configured on this device.';
130	    case 'auth_required':
131	      return 'Sign-in is required; cached conversations stay readable.';
132	    case 'auth_cancelled':
133	      return 'Sign-in was cancelled.';
134	    case 'auth_failed':
135	      return 'Sign-in failed. Cached conversations stay readable.';
136	    case 'secrets_unavailable':
137	      return 'Secure credential storage is unavailable.';
138	    case 'network_unavailable':
139	      return 'The network is unavailable; cached conversations stay readable.';
140	    case 'rate_limited':
141	      return 'The provider is rate limiting. Cached conversations stay readable.';
142	    case 'provider_unavailable':
143	      return 'The mail provider is temporarily unavailable.';
144	    case 'invalid_provider_response':
145	      return 'The provider returned an unexpected response.';
146	    case 'busy':
147	      return 'A sync is already in progress. Try again shortly.';
148	    case 'permission_required':
149	      return 'Google mailbox-action permission is not enabled.';
150	    case 'provider_rejected':
151	      return 'The provider rejected this action.';
152	    case 'outcome_unknown':
153	      return 'The remote result is uncertain. Review Activity before retrying.';
154	    default:
155	      return 'Could not load the conversation.';
156	  }
157	}
158	
159	// ---------------------------------------------------------------------------
160	// Visit-scoped message state, keyed by account+conversation
161	// ---------------------------------------------------------------------------
162	
163	/** Viewport-relative scroll anchor: a message top plus a scrollTop fallback. */
164	interface MessageAnchor { messageId: string; offsetTop: number; scrollTop: number }
165	
166	interface VisitState {
167	  activeMessageId: string | null;
168	  expandedIds: Set<string>;
169	  detailsOpenId: string | null;
170	  anchor: MessageAnchor | null;
171	  /** Message ordering this state was built against (for removed-ID resolution). */
172	  order: string[];
173	}
174	
175	const visits = new Map<string, VisitState>();
176	/** Reactive holder for the currently displayed visit. */
177	const visitRef = ref<VisitState | null>(null);
178	let lastDataKey: string | null = null;
179	/**
180	 * Foreground activation intent, tracked separately from `lastDataKey`: a
181	 * loading transition that removed reader-owned focus owes the next ready
182	 * snapshot a message-focus restoration, even when the user reverses back to
183	 * the same key as the last loaded one (which would otherwise be classified as
184	 * an unfocused same-reference background replacement).
185	 */
186	let pendingFocusRestore = false;
187	
188	function visitKey(ref: ConversationRef): string {
189	  return `${ref.accountId}:${ref.conversationId}`;
190	}
191	
192	function keyOfDisplayed(): string | null {
193	  const conversation = props.conversation;
194	  const open = props.openRef;
195	  if (!conversation || !open) return null;
196	  if (conversation.ref.accountId !== open.accountId || conversation.ref.conversationId !== open.conversationId) return null;
197	  return visitKey(conversation.ref);
198	}
199	
200	/**
201	 * Prune removed message IDs and resolve removed active/anchor IDs by the
202	 * surviving old neighbors (next surviving old neighbor, then previous), so a
203	 * background replacement can never leave a stale message target.
204	 */
205	function pruneVisit(visit: VisitState, nextIds: string[]): void {
206	  const present = new Set(nextIds);
207	  const resolve = (id: string | null): string | null => {
208	    if (id === null || present.has(id)) return id;
209	    const oldIndex = visit.order.indexOf(id);
210	    if (oldIndex >= 0) {
211	      for (let i = oldIndex + 1; i < visit.order.length; i += 1) {
212	        const candidate = visit.order[i]!;
213	        if (present.has(candidate)) return candidate;
214	      }
215	      for (let i = oldIndex - 1; i >= 0; i -= 1) {
216	        const candidate = visit.order[i]!;
217	        if (present.has(candidate)) return candidate;
218	      }
219	    }
220	    return null;
221	  };
222	  visit.activeMessageId = resolve(visit.activeMessageId);
223	  visit.detailsOpenId = visit.detailsOpenId !== null && present.has(visit.detailsOpenId) ? visit.detailsOpenId : null;
224	  if (visit.anchor && !present.has(visit.anchor.messageId)) {
225	    const resolved = resolve(visit.anchor.messageId);
226	    visit.anchor = resolved
227	      ? { ...visit.anchor, messageId: resolved }
228	      : { messageId: '', offsetTop: 0, scrollTop: visit.anchor.scrollTop };
229	  }
230	  visit.expandedIds = new Set([...visit.expandedIds].filter((id) => present.has(id)));
231	  visit.order = [...nextIds];
232	}
233	
234	function captureScrollAnchor(visit: VisitState): MessageAnchor | null {
235	  const scroller = scrollerEl.value;
236	  if (!scroller || visit.order.length === 0) return null;
237	  const scrollerTop = scroller.getBoundingClientRect().top;
238	  for (const id of visit.order) {
239	    const el = messageEls.get(id);
240	    if (!el) continue;
241	    const top = el.getBoundingClientRect().top;
242	    if (top >= scrollerTop - 1 || id === visit.order[visit.order.length - 1]) {
243	      return { messageId: id, offsetTop: top - scrollerTop, scrollTop: scroller.scrollTop };
244	    }
245	  }
246	  return null;
247	}
248	
249	function restoreScroll(visit: VisitState, scroller: HTMLElement): void {
250	  const anchor = visit.anchor;
251	  if (!anchor) return;
252	  const el = messageEls.get(anchor.messageId);
253	  if (!el || scroller.clientHeight === 0 || !anchor.messageId) {
254	    // Fallback: the anchored message no longer exists; restore the raw offset.
255	    scroller.scrollTop = anchor.scrollTop;
256	    return;
257	  }
258	  const relative = el.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
259	  scroller.scrollTop = scroller.scrollTop + (relative - anchor.offsetTop);
260	}
261	
262	function focusElement(el: HTMLElement | null | undefined, reveal: boolean): boolean {
263	  if (!el || !el.isConnected) return false;
264	  // Never move focus into an inert ancestor (e.g. a drawer covering the reader).
265	  if (el.closest('[inert]')) return false;
266	  el.focus({ preventScroll: true });
267	  if (reveal && typeof el.scrollIntoView === 'function') el.scrollIntoView({ block: 'nearest' });
268	  return document.activeElement === el;
269	}
270	
271	function focusMessageToggle(messageId: string, reveal: boolean): void {
272	  focusElement(messageEls.get(messageId)?.querySelector<HTMLElement>('.message-toggle'), reveal);
273	}
274	
275	type ComponentPublicInstance = import('vue').ComponentPublicInstance;
276	
277	function setMessageEl(el: Element | ComponentPublicInstance | null, messageId: string): void {
278	  if (el instanceof HTMLElement) messageEls.set(messageId, el);
279	  else messageEls.delete(messageId);
280	}
281	
282	let updateSeq = 0;
283	
284	/**
285	 * Loading teardown: if reader-owned focus was dropped to <body> because the
286	 * loading placeholder removed the focused message control, park it on the
287	 * persistent reader article. Never steals toolbar, rail, overlay, or other
288	 * unrelated focus — including a surface the user moved to while this delayed
289	 * work was in flight — respects inert ancestors, and is invalidated by any
290	 * newer update (a ready snapshot takes over via schedulePostUpdate).
291	 */
292	async function scheduleLoadingFocus(seq: number): Promise<void> {
293	  await nextTick();
294	  if (seq !== updateSeq) return;
295	  // Focus already lives on a surviving reader surface (e.g. the toolbar);
296	  // leave it exactly where it is.
297	  if (container.value?.contains(document.activeElement) ?? false) return;
298	  // Park only over focus that fell to <body> when the message control was
299	  // torn down: a still-focused rail/outside button keeps its focus.
300	  const active = document.activeElement;
301	  if (active !== null && active !== document.body) return;
302	  focusElement(container.value, false);
303	}
304	
305	/**
306	 * Post-update work for one conversation snapshot: restore the visit's scroll
307	 * position and, on a visit switch, focus the visit's active message toggle
308	 * (the article stays the empty/error fallback). The delayed focus is guarded
309	 * against a changed reference, a newer update, and inert ancestors.
310	 */
311	async function schedulePostUpdate(key: string, focusIntent: boolean, readerHadFocus: boolean, restoringAfterLoading: boolean): Promise<void> {
312	  const seq = ++updateSeq;
313	  await nextTick();
314	  if (seq !== updateSeq || keyOfDisplayed() !== key) return;
315	  const visit = visits.get(key);
316	  const scroller = scrollerEl.value;
317	  if (visit && scroller) restoreScroll(visit, scroller);
318	  const messages = props.conversation?.messages ?? [];
319	  // A replacement that removed the focused message element must not drop
320	  // reader focus to <body>; resolve it to the visit's active message toggle.
321	  if (!focusIntent && readerHadFocus && !(container.value?.contains(document.activeElement) ?? false)) {
322	    if (messages.length === 0 || !visit?.activeMessageId) {
323	      focusElement(container.value, false);
324	      return;
325	    }
326	    // Scroll geometry was just restored; do not let focus-reveal shift it.
327	    focusMessageToggle(visit.activeMessageId, false);
328	    return;
329	  }
330	  if (!focusIntent) return;
331	  if (restoringAfterLoading) {
332	    // A delayed reversal must not yank focus from a surface the user moved to
333	    // while the loading placeholder was up: only our own parked article focus
334	    // (or focus that fell to <body>) may be promoted to a restoration target.
335	    // This ownership check must come BEFORE choosing the target so it also
336	    // protects the empty-visit article fallback, not just the message toggle.
337	    const active = document.activeElement;
338	    const inReader = active instanceof Node && (container.value?.contains(active) ?? false);
339	    if (inReader ? active !== container.value : active !== null && active !== document.body) return;
340	  }
341	  if (messages.length === 0 || !visit?.activeMessageId) {
342	    // Empty/error fallback: the reader article keeps focus instead of a
343	    // message control that does not exist.
344	    focusElement(container.value, false);
345	    return;
346	  }
347	  // A revisit with a saved anchor is positioned by restoreScroll; focusing
348	  // must not reveal-scroll and destroy the restored reading offset. A first
349	  // visit has no geometry yet, so reveal the focused header as needed.
350	  focusMessageToggle(visit.activeMessageId, visit.anchor === null);
351	}
352	
353	watch(
354	  () => props.conversation,
355	  (conversation) => {
356	    // Capture the outgoing visit's scroll geometry BEFORE any DOM teardown,
357	    // including the foreground null/loading transition: useMailbox clears the
358	    // conversation before the next detail arrives, and by the following
359	    // non-null update the outgoing message elements are already gone. This
360	    // watcher runs pre-flush, so the old elements are still live here. The
361	    // capture is a no-op once the elements are gone, so a loading/empty DOM
362	    // can never overwrite a saved anchor.
363	    const outgoing = lastDataKey !== null ? visits.get(lastDataKey) : null;
364	    if (outgoing && scrollerEl.value) {
365	      const captured = captureScrollAnchor(outgoing);
366	      if (captured) outgoing.anchor = captured;
367	    }
368	    const readerHadFocus = container.value?.contains(document.activeElement) ?? false;
369	    if (!conversation) {
370	      // Loading/error: visit state must not be erased. Only reader-owned
371	      // focus that is about to lose its message control is parked on the
372	      // persistent reader article (not <body>) and remembered for message
373	      // focus restoration on the next ready snapshot even when it resolves to
374	      // the last loaded key (immediate reversal). Focus that already lives
375	      // elsewhere (rail/overlay/outside) is never scheduled over.
376	      const seq = ++updateSeq;
377	      if (readerHadFocus) {
378	        pendingFocusRestore = true;
379	        void scheduleLoadingFocus(seq);
380	      }
381	      return;
382	    }
383	    const key = visitKey(conversation.ref);
384	    const previousKey = lastDataKey;
385	    const ids = conversation.messages.map((message) => message.id);
386	    let visit = visits.get(key);
387	    if (!visit) {
388	      const newest = ids[ids.length - 1] ?? null;
389	      // Reactive so state mutations (pruning resolution, command handlers)
390	      // publish through visitRef to templates and the active-ID watcher.
391	      visit = reactive<VisitState>({
392	        activeMessageId: newest,
393	        expandedIds: new Set(newest === null ? [] : [newest]),
394	        detailsOpenId: null,
395	        anchor: null,
396	        order: [...ids],
397	      });
398	      visits.set(key, visit);
399	    } else {
400	      pruneVisit(visit, ids);
401	    }
402	    visitRef.value = visit;
403	    lastDataKey = key;
404	    // Foreground activation is tracked separately from the last loaded key:
405	    // a reversal back to the same key still owes a focus restoration.
406	    const restoringAfterLoading = pendingFocusRestore;
407	    pendingFocusRestore = false;
408	    // A same-reference replacement never changes focus; a visit switch or a
409	    // reversed loading transition does.
410	    void schedulePostUpdate(key, key !== previousKey || restoringAfterLoading, readerHadFocus, restoringAfterLoading);
411	  },
412	  { immediate: true, flush: 'pre' },
413	);
414	
415	/** Loading/error fallback: keep the reader article focused, never steal toolbar focus. */
416	watch(
417	  () => props.state,
418	  async (state) => {
419	    if (state !== 'error') return;
420	    const seq = ++updateSeq;
421	    await nextTick();
422	    if (seq !== updateSeq) return;
423	    const active = document.activeElement;
424	    if (active instanceof Node && container.value?.contains(active)) return;
425	    focusElement(container.value, false);
426	  },
427	);
428	
429	// Reader focus identity + participant context (App consumes these).
430	watch(
431	  () => visitRef.value?.activeMessageId ?? null,
432	  (activeId) => { emit('activeMessage', activeId); },
433	  { immediate: true },
434	);
435	
436	const hoverParticipant = ref<{ messageId: string; address: Address } | null>(null);
437	const focusParticipant = ref<{ messageId: string; address: Address } | null>(null);
438	// Keyboard focus overrides hover independently; both restore the baseline on exit.
439	const effectiveParticipant = computed(() => focusParticipant.value ?? hoverParticipant.value);
440	
441	watch(
442	  effectiveParticipant,
443	  (value) => {
444	    const open = props.openRef;
445	    if (!value || !open) {
446	      emit('contactOverride', null);
447	      return;
448	    }
449	    emit('contactOverride', {
450	      ref: { ...open },
451	      messageId: value.messageId,
452	      displayName: value.address.displayName,
453	      mailbox: value.address.mailbox,
454	    });
455	  },
456	);
457	
458	function sameParticipant(
459	  current: { messageId: string; address: Address } | null,
460	  messageId: string,
461	  address: Address,
462	): boolean {
463	  return current !== null && current.messageId === messageId && current.address.mailbox === address.mailbox;
464	}
465	
466	function onParticipantEnter(message: Message, address: Address): void {
467	  hoverParticipant.value = { messageId: message.id, address };
468	}
469	
470	function onParticipantLeave(message: Message, address: Address): void {
471	  if (sameParticipant(hoverParticipant.value, message.id, address)) hoverParticipant.value = null;
472	}
473	
474	function onParticipantFocus(message: Message, address: Address): void {
475	  focusParticipant.value = { messageId: message.id, address };
476	}
477	
478	function onParticipantBlur(message: Message, address: Address): void {
479	  if (sameParticipant(focusParticipant.value, message.id, address)) focusParticipant.value = null;
480	}
481	
482	// ---------------------------------------------------------------------------
483	// Message rendering helpers + narrow message commands (exposed to App)
484	// ---------------------------------------------------------------------------
485	
486	/**
487	 * The visit a message command may act on: only a ready, matching displayed
488	 * reference qualifies. During loading the outgoing visit stays saved for
489	 * restoration, but stale commands must never mutate it.
490	 */
491	function displayedVisit(): VisitState | null {
492	  if (props.state !== 'ready') return null;
493	  const key = keyOfDisplayed();
494	  return key !== null ? visits.get(key) ?? null : null;
495	}
496	
497	function isActive(message: Message): boolean {
498	  return visitRef.value?.activeMessageId === message.id;
499	}
500	
501	/** Roving tabindex: the active toggle is the tab stop; the first is the fallback. */
502	function tabIndexFor(message: Message): 0 | -1 {
503	  if (isActive(message)) return 0;
504	  if ((visitRef.value?.activeMessageId ?? null) === null && message.id === (props.conversation?.messages[0]?.id ?? null)) return 0;
505	  return -1;
506	}
507	
508	function isExpanded(message: Message): boolean {
509	  return visitRef.value?.expandedIds.has(message.id) ?? false;
510	}
511	
512	function isDetailsOpen(message: Message): boolean {
513	  return visitRef.value?.detailsOpenId === message.id;
514	}
515	
516	function bodyId(message: Message): string {
517	  return `reader-body-${props.conversation?.ref.accountId}-${message.id}`.replace(/[^A-Za-z0-9_-]/g, '-');
518	}
519	
520	function setActive(messageId: string): void {
521	  const visit = visitRef.value;
522	  if (visit && visit.activeMessageId !== messageId) visit.activeMessageId = messageId;
523	}
524	
525	function setActiveByFocus(message: Message): void {
526	  // Focusing any control of a message updates its message identity.
527	  setActive(message.id);
528	}
529	
530	function toggleMessage(message: Message): void {
531	  const visit = visitRef.value;
532	  if (!visit) return;
533	  setActive(message.id);
534	  if (visit.expandedIds.has(message.id)) visit.expandedIds.delete(message.id);
535	  else visit.expandedIds.add(message.id);
536	}
537	
538	function onDetailsToggle(event: Event, message: Message): void {
539	  const visit = visitRef.value;
540	  if (!visit) return;
541	  const open = (event.target as HTMLDetailsElement).open;
542	  if (open && visit.detailsOpenId !== message.id) visit.detailsOpenId = message.id;
543	  else if (!open && visit.detailsOpenId === message.id) {
544	    visit.detailsOpenId = null;
545	    // Dismissing the disclosure ends its participant context: a browser may
546	    // keep focus inside the closed disclosure without firing blur, so clear
547	    // the keyboard-held override for this message explicitly.
548	    if (focusParticipant.value?.messageId === message.id) focusParticipant.value = null;
549	    if (hoverParticipant.value?.messageId === message.id) hoverParticipant.value = null;
550	  }
551	}
552	
553	/** N/P: move message focus without implicitly expanding (no wrap). */
554	function moveMessage(delta: number): void {
555	  const visit = displayedVisit();
556	  const messages = props.conversation?.messages ?? [];
557	  if (!visit || messages.length === 0) return;
558	  const ids = messages.map((message) => message.id);
559	  const index = visit.activeMessageId ? ids.indexOf(visit.activeMessageId) : -1;
560	  const targetIndex = index < 0
561	    ? (delta > 0 ? 0 : ids.length - 1)
562	    : Math.min(ids.length - 1, Math.max(0, index + delta));
563	  const target = messages[targetIndex]!;
564	  setActive(target.id);
565	  // Explicit movement reveals the target header as needed.
566	  focusMessageToggle(target.id, true);
567	}
568	
569	/** O: expand/collapse the focused message. */
