/*
 * Rail + one central list-or-reader surface + contact context. The contact
 * column exists only at >=1000 CSS px; strictly below it, the rail exposes a
 * keyboard-operable Contact disclosure instead.
 */
.app-main {
  /* Shell body type: everything not on another step of the scale is 12px. */
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  /* Header, static in-flow notices, the list-or-reader surface, then the
     bottom dock (selection, action outcome, command error); the rail and
     contact pane span all four so the header lives in the list column. */
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  flex: 1;
  min-height: 0;
  position: relative;
}

.app-main > .rail {
  grid-column: 1;
  grid-row: 1 / -1;
}

.app-main > .app-header,
.app-main > .list-notices,
.app-main > .list-dock {
  grid-column: 2;
}

.app-main > .app-header { grid-row: 1; }
.app-main > .list-notices { grid-row: 2; min-width: 0; }
.app-main > .list-dock { grid-row: 4; }

.app-main > .central,
.app-main > .account-gate {
  grid-column: 2;
  grid-row: 3;
}

.app-main > .contact-column {
  grid-column: 3;
  grid-row: 1 / -1;
}

@media (min-width: 1000px) {
  .app-main {
    grid-template-columns: auto minmax(0, 1fr) var(--contact-width);
  }
}

.rail {
  /* 40px icon rail (DESIGN.md "Rail"). Fixed px so larger root fonts widen
     the list, never the rail. Above the row-actions popover (6), below the
     utility drawers (30), so the keyboard tooltip clears the list. */
  position: relative;
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: var(--rail-width);
  grid-column: 1 / -1;
}

.composer-fields label:has(textarea) {
  grid-column: 1 / -1;
}

@media (max-width: 760px) {
  .drafts-pane {
    grid-template-columns: 1fr;
  }
}

